// TOPS CORE — Dual-Engine Screen Wake Lock (Native W3C API + Media Fallback)
// Keeps participant's screen awake during tests across all mobile devices (Android / iOS / Windows / macOS)
// Works on both Secure Contexts (HTTPS/localhost) and Local Area Network HTTP (http://192.168.x.x)

const SILENT_MP4 = 'data:video/mp4;base64,';
const SILENT_WEBM = 'data:video/webm;base64,';

let nativeSentinel = null;
let fallbackVideo = null;
let isArmed = false;
let pulseTimer = null;
let gestureListenersBound = false;

export const wakeLockState = {
  requested: false,
  nativeActive: false,
  fallbackActive: false,
  lastError: null
};

/**
 * Initializes the video fallback element in DOM.
 */
function ensureFallbackVideo() {
  if (fallbackVideo || typeof document === 'undefined') return fallbackVideo;

  try {
    const v = document.createElement('video');
    v.setAttribute('playsinline', '');
    v.setAttribute('webkit-playsinline', '');
    v.setAttribute('muted', '');
    v.setAttribute('loop', '');
    v.muted = true;
    v.loop = true;
    v.preload = 'auto';
    v.style.cssText = 'position:fixed;width:1px;height:1px;left:-999px;top:-999px;opacity:0.001;pointer-events:none;z-index:-1000;';

    // Source 1: WebM (Chrome Android, Firefox, Opera)
    const srcWebm = document.createElement('source');
    srcWebm.src = SILENT_WEBM;
    srcWebm.type = 'video/webm';
    v.appendChild(srcWebm);

    // Source 2: MP4 (iOS Safari, Samsung Internet, Chromium)
    const srcMp4 = document.createElement('source');
    srcMp4.src = SILENT_MP4;
    srcMp4.type = 'video/mp4';
    v.appendChild(srcMp4);

    document.body.appendChild(v);
    fallbackVideo = v;
  } catch (err) {
    console.warn('[WakeLock] Fallback video creation error:', err);
  }
  return fallbackVideo;
}

/**
 * Plays the fallback video loop to trick OS into keeping screen alive.
 */
async function playFallbackVideo() {
  const v = ensureFallbackVideo();
  if (!v) return false;
  try {
    v.muted = true;
    const playPromise = v.play();
    if (playPromise !== undefined) {
      await playPromise;
    }
    wakeLockState.fallbackActive = true;
    return true;
  } catch (err) {
    wakeLockState.fallbackActive = false;
    return false;
  }
}

/**
 * Requests native W3C Screen Wake Lock API.
 */
async function requestNativeLock() {
  if (typeof navigator === 'undefined' || !('wakeLock' in navigator)) {
    return false;
  }
  if (nativeSentinel) return true;

  try {
    nativeSentinel = await navigator.wakeLock.request('screen');
    wakeLockState.nativeActive = true;
    wakeLockState.lastError = null;

    nativeSentinel.addEventListener('release', () => {
      nativeSentinel = null;
      wakeLockState.nativeActive = false;
      // If test is still active and user is still on page, try to re-acquire
      if (isArmed && document.visibilityState === 'visible') {
        requestNativeLock().catch(() => {});
      }
    });

    // Native lock acquired successfully
    return true;
  } catch (err) {
    wakeLockState.nativeActive = false;
    wakeLockState.lastError = err.message || String(err);
    return false;
  }
}

/**
 * Main function to acquire Screen Wake Lock across both engines.
 */
export async function requestScreenWakeLock() {
  isArmed = true;
  wakeLockState.requested = true;

  // 1. Try Native W3C Wake Lock API first
  const nativeOk = await requestNativeLock();

  // 2. Regardless of native support, or if native is unsupported / failed (e.g. HTTP on LAN / lack of user gesture),
  // spin up silent media loop fallback so mobile OS NEVER dims the screen
  const fallbackOk = await playFallbackVideo();

  // 3. Start pulse timer to ensure lock doesn't drop
  if (!pulseTimer && typeof window !== 'undefined') {
    pulseTimer = setInterval(() => {
      if (!isArmed) return;
      if (document.visibilityState === 'visible') {
        if (!nativeSentinel && 'wakeLock' in navigator) {
          requestNativeLock().catch(() => {});
        }
        if (fallbackVideo && fallbackVideo.paused) {
          fallbackVideo.play().catch(() => {});
        }
      }
    }, 15000);
  }

  // Bind interaction listeners if not yet bound
  bindWakeLockGestures();

  if (typeof window !== 'undefined') {
    window.wakeLockState = wakeLockState;
  }

  return { native: nativeOk, fallback: fallbackOk };
}

/**
 * Releases all screen wake locks when test completes or leaves.
 */
export function releaseScreenWakeLock() {
  isArmed = false;
  wakeLockState.requested = false;

  if (pulseTimer) {
    clearInterval(pulseTimer);
    pulseTimer = null;
  }

  if (nativeSentinel) {
    try { nativeSentinel.release(); } catch (_) {}
    nativeSentinel = null;
    wakeLockState.nativeActive = false;
  }

  if (fallbackVideo) {
    try {
      fallbackVideo.pause();
      fallbackVideo.currentTime = 0;
    } catch (_) {}
    wakeLockState.fallbackActive = false;
  }

  // Screen lock released
}

/**
 * Hooks into student touch / click gestures to guarantee browser autoplay
 * and permissions policies allow keeping screen awake.
 */
export function bindWakeLockGestures() {
  if (gestureListenersBound || typeof document === 'undefined') return;
  gestureListenersBound = true;

  const onGesture = () => {
    if (isArmed) {
      if (!nativeSentinel && 'wakeLock' in navigator) {
        requestNativeLock().catch(() => {});
      }
      if (fallbackVideo && fallbackVideo.paused) {
        fallbackVideo.play().catch(() => {});
      }
    }
  };

  const events = ['click', 'touchstart', 'touchend', 'pointerdown', 'keydown'];
  events.forEach(ev => {
    document.addEventListener(ev, onGesture, { passive: true, capture: true });
  });

  // Re-acquire on tab visibility
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible' && isArmed) {
      requestScreenWakeLock().catch(() => {});
    }
  });
}

export function getWakeLockStatus() {
  return {
    isArmed,
    nativeActive: !!nativeSentinel,
    fallbackActive: !!(fallbackVideo && !fallbackVideo.paused),
    supported: typeof navigator !== 'undefined' && 'wakeLock' in navigator
  };
}
